import { Component, Input, SimpleChanges } from '@angular/core';
import { Carrito} from 'src/app/models/carrito';
import { CarritoService } from 'src/app/services/carrito.service';

@Component({
  selector: 'app-carrito',
  templateUrl: './carrito.component.html',
  styleUrls: ['./carrito.component.css']
})
export class CarritoComponent {
  public carrito: Carrito = new Carrito;
  @Input() emailUsuario : string;

  constructor(public carritoService: CarritoService) {
    this.emailUsuario="";
   }

   ngOnInit(): void {
    this.conseguirCarrito("null");
   }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['emailUsuario'].currentValue || changes['this.carrito'].currentValue) {
      let email = changes['emailUsuario'].currentValue;
      console.log('Nuevo email de usuario carrito:', email);
      this.emailUsuario = email;
      this.conseguirCarrito(this.emailUsuario);
    }

  }
  conseguirCarrito(email: string){
    this.carritoService.obtenerCarrito(email).subscribe(
      (res: any) => { 
        this.carrito = res;
        this.carritoService.carritoSeleccionado = res;
        console.log(this.carrito);
      },
      error => { console.error('Error: ', error); }
    );
  }
  

}
<div class="card">
  <div class="card-body">
    <h5 class="card-title">Carrito de compras <i class="bi bi-cart" style="font-size: 24px; margin: 0 10px;"></i></h5>
    
    <div *ngFor="let producto of carrito.productos">
      <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px;">
        <div>
          <h6 class="card-subtitle text-muted">{{producto.nombreProd}}</h6>
          <p class="card-text" style="font-size: 12px;">Unidades: {{producto.cantidad}}</p>
        
          Precio: {{producto.precio}}
        
        </div>
        <div style="display: flex; align-items: center;">
          <button class="btn btn-success">-</button>
          <input type="number" max="100" min="1" value="1" style="margin-right: 10px;">
          <button class="btn btn-success">+</button>
          <button class="btn btn-danger">X</button>
        </div>
      </div>
    </div>

    <p class="card-text" id="ptotal" style="font-size: 16px;">Total: {{carrito.total}}</p>
    <a href="#" class="btn btn-primary">Comprar</a>
  </div>
</div>
